window.__PAGES=window.__PAGES||{};window.__PAGES["pages/broadcast-templates.html"]="<!-- Broadcast Template — card grid of WA templates -->\n<div class=\"broadcast-layout\">\n  <aside class=\"broadcast-sidenav\">\n    <div class=\"sn-title\">Broadcast Massal</div>\n    <div class=\"sn-item\" onclick=\"go('broadcast/messages')\">📢 Pesan</div>\n    <div class=\"sn-item\" onclick=\"go('broadcast/draft')\">📝 Draft</div>\n    <div class=\"sn-item active\" onclick=\"go('broadcast/templates')\">📋 Template</div>\n  </aside>\n  <div class=\"broadcast-body\">\n    <div class=\"page-header\">\n      <h1>Template Pesan</h1>\n      <button class=\"btn primary\" onclick=\"openTplModal()\">+ Buat Template</button>\n    </div>\n    <div class=\"page-body\" id=\"tplGrid\" style=\"display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:12px\"></div>\n  </div>\n</div>\n\n<!-- Modal -->\n<div class=\"modal-overlay\" id=\"tplModal\">\n  <div class=\"modal\">\n    <h3 id=\"tplModalTitle\">Buat Template</h3>\n    <label>Nama Template<input type=\"text\" id=\"tplName\" placeholder=\"contoh: promo_ramadan\"></label>\n    <label>Isi Pesan<textarea id=\"tplBody\" rows=\"4\" placeholder=\"Gunakan {{1}}, {{2}} untuk variabel\"></textarea></label>\n    <label>Bahasa<select id=\"tplLang\"><option value=\"id\">Indonesia</option><option value=\"en\">English</option></select></label>\n    <div class=\"modal-actions\">\n      <button class=\"btn\" onclick=\"closeTplModal()\">Batal</button>\n      <button class=\"btn primary\" onclick=\"saveTpl()\">Simpan</button>\n    </div>\n  </div>\n</div>\n\n<script>\nlet tplEditId=null;\n\nfunction tplStatusColor(s){\n  return s==='approved'?'background:#dcfce7;color:#15803d':s==='pending'?'background:#fef3c7;color:#b45309':'background:#fef2f2;color:#ef4444';\n}\n\nfunction renderTplGrid(){\n  const el=document.getElementById('tplGrid');\n  el.innerHTML=DB.templates.map(t=>`\n    <div class=\"card\">\n      <div style=\"display:flex;align-items:center;justify-content:space-between;margin-bottom:8px\">\n        <b>${t.name}</b>\n        <span style=\"font-size:11px;font-weight:600;padding:2px 8px;border-radius:10px;${tplStatusColor(t.status)}\">${t.status}</span>\n      </div>\n      <div style=\"font-size:13px;color:var(--muted);margin-bottom:12px;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden\">${t.body}</div>\n      <div style=\"font-size:11px;color:var(--muted)\">Bahasa: ${t.lang==='id'?'Indonesia':'English'}</div>\n      <div style=\"margin-top:10px;display:flex;gap:6px\">\n        <button class=\"btn\" onclick=\"editTpl('${t.id}')\" style=\"font-size:11px\">✏️ Edit</button>\n        <button class=\"btn danger\" onclick=\"delTpl('${t.id}')\" style=\"font-size:11px\">🗑 Hapus</button>\n      </div>\n    </div>\n  `).join('')||'<div style=\"text-align:center;color:var(--muted);padding:40px;grid-column:1/-1\">Belum ada template</div>';\n}\n\nfunction openTplModal(id){\n  tplEditId=id||null;\n  document.getElementById('tplModalTitle').textContent=id?'Edit Template':'Buat Template';\n  if(id){\n    const t=dbFind('templates',id);\n    document.getElementById('tplName').value=t.name;\n    document.getElementById('tplBody').value=t.body;\n    document.getElementById('tplLang').value=t.lang;\n  }else{\n    document.getElementById('tplName').value='';\n    document.getElementById('tplBody').value='';\n    document.getElementById('tplLang').value='id';\n  }\n  document.getElementById('tplModal').classList.add('open');\n}\nfunction closeTplModal(){document.getElementById('tplModal').classList.remove('open')}\n\nfunction saveTpl(){\n  const name=document.getElementById('tplName').value.trim();\n  const body=document.getElementById('tplBody').value.trim();\n  if(!name||!body)return showToast('Nama dan isi pesan wajib diisi');\n  const lang=document.getElementById('tplLang').value;\n  if(tplEditId){\n    dbUpdate('templates',tplEditId,{name,body,lang});\n    showToast('Template diperbarui');\n  }else{\n    dbAdd('templates',{id:genId('tpl'),name,status:'pending',body,lang});\n    showToast('Template dibuat');\n  }\n  closeTplModal();renderTplGrid();\n}\n\nfunction editTpl(id){openTplModal(id)}\nfunction delTpl(id){dbRemove('templates',id);renderTplGrid();showToast('Template dihapus')}\n\nrenderTplGrid();\n</script>\n";
